import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

// Owned elsewhere: course skills (upstream), CHANGELOG.md (written by
// semantic-release), infra/sdks (generated by `pulumi package add`) and the AI
// Catalog mapping (committed by the ai-catalog component).
const owned = [
  ".claude/skills/**",
  ".gitlab/duo/catalog/mapping.json",
  "CHANGELOG.md",
  "infra/sdks/**",
];

export default defineConfig({
  ...ultracite,
  ignorePatterns: [...(ultracite.ignorePatterns ?? []), ...owned],
});
